UPDATE sys10_file
   SET sys10_tdm_check_form_type = #{formType},
       sys10_note                = #{note}
 WHERE sys10_file_id   = #{fileId}
   AND sys10_parent_id = #{companyId}

UPDATE sys10_file
   SET sys10_tdm_check_form_type = #{formType},
       sys10_note                = #{note},
       sys10_person_id           = #{personId}
 WHERE sys10_file_id = #{fileId}
